/**
 * ServerAsset
 *
 * An asset a media server shows for an item: one artwork slot, or the theme.
 *
 * A refresh unlocks exactly the assets it is meant to replace.
 */
export type ServerAsset = 'poster' | 'background' | 'season_poster' | 'theme';

