export type SyncRunRequest = {
    library_ids?: LibraryIds | null;
};

/**
 * SyncScheduleConfig
 *
 * What one saved sync schedule runs.
 */
export type SyncScheduleConfigInput = {
    /**
     * Download Overturedb Art
     *
     * Incremental only: queue OvertureDB art for new items.
     */
    download_overturedb_art?: boolean;
    /**
     * Incremental only: queue themes for new items.
     */
    download_themes?: IncrementalThemeOrder;
    /**
     * Libraries to sync; empty means every library.
     */
    library_ids?: LibraryIds;
    mode?: SyncScheduleMode;
};

/**
 * SyncScheduleConfig
 *
 * What one saved sync schedule runs.
 */
export type SyncScheduleConfigOutput = {
    /**
     * Download Overturedb Art
     *
     * Incremental only: queue OvertureDB art for new items.
     */
    download_overturedb_art: boolean;
    /**
     * Incremental only: queue themes for new items.
     */
    download_themes: IncrementalThemeOrder;
    /**
     * Libraries to sync; empty means every library.
     */
    library_ids: LibraryIds;
    mode: SyncScheduleMode;
};

export type SyncScheduleMode = 'full' | 'incremental';

